with lines as (select id, host, latency_ms, status_code, attr_key, v from app_logs lateral view outer explode(context) li as attr_key, v), unpacked as (select latency_ms, status_code, attr_key, v, cast((status_code & 2) != 0 as int) as flag_bit2, shiftright(status_code, 2) as status_code_high from lines), base as (select latency_ms, status_code, attr_key, flag_bit2, status_code_high, greatest(latency_ms, status_code) as greatest_latency_ms_status_code from unpacked where attr_key is not null), scored as (select latency_ms, status_code, flag_bit2, greatest_latency_ms_status_code, dense_rank() over (partition by attr_key order by status_code_high asc nulls first) as status_code_high_dense_rank, min(status_code_high) over (partition by attr_key) as attr_key_min_status_code_high from base where greatest_latency_ms_status_code <= 27) select case when flag_bit2 >= 1 then 'LARGE' else 'SMALL' end as flag_bit2_tier, case when attr_key_min_status_code_high >= 2 then 'PREMIUM' else 'STANDARD' end as attr_key_min_status_code_high_tier, max(attr_key_min_status_code_high) as max_attr_key_min_status_code_high, avg(attr_key_min_status_code_high) as avg_attr_key_min_status_code_high, percentile_approx(flag_bit2, 0.5) as flag_bit2_p50, corr(status_code, latency_ms) as corr_status_code_latency_ms, stddev_samp(latency_ms) as latency_ms_stddev, percentile_approx(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles from scored group by case when flag_bit2 >= 1 then 'LARGE' else 'SMALL' end, case when attr_key_min_status_code_high >= 2 then 'PREMIUM' else 'STANDARD' end having flag_bit2_p50 >= 0
